# Generated by forge. Django REST framework views declare who may call them (run by
# .forge/check.sh with the project's own Python). Usage:
#   python drf_permissions.py <forge-tmp> [path...]
# The default is read from the settings module Django runs with: the
# DJANGO_SETTINGS_MODULE that manage.py, wsgi.py or asgi.py sets (star imports
# followed), else a settings.py or settings/ package outside tests. When it does not
# set REST_FRAMEWORK["DEFAULT_PERMISSION_CLASSES"] to a non-empty list without
# AllowAny (DRF's default is AllowAny), each class that inherits a DRF APIView,
# generic view or viewset (directly or through the project's own classes, mixins of
# any kind included) must get a non-empty permission_classes (or get_permissions)
# from itself or a project ancestor, and each @api_view function must have
# @permission_classes. permission_classes = [] declares nothing.
# Exit 0: nothing found; 1: findings printed; 3: cannot run ("skipped: ..." printed).
import ast
import re
import subprocess
import sys

DRF_BASE = re.compile(r"^(APIView|GenericAPIView|(List|Create|Retrieve|Update|Destroy|ListCreate|RetrieveUpdate|RetrieveDestroy|RetrieveUpdateDestroy)APIView|ViewSet|GenericViewSet|ModelViewSet|ReadOnlyModelViewSet|ViewSetMixin)$")


TESTS = re.compile(r"(^|/)(tests?/|test_[^/]*$|[^/]*_test\.py$|conftest\.py$|migrations/)")


def tracked_py():
    try:
        out = subprocess.run(["git", "ls-files", "-co", "--exclude-standard", "*.py"], capture_output=True, text=True, check=True).stdout
    except Exception:
        return []
    return [p for p in out.splitlines() if p]


def parse(path):
    try:
        with open(path, encoding="utf-8") as f:
            src = f.read()
        return src, ast.parse(src, path)
    except (OSError, SyntaxError, ValueError):
        return None, None


def last_name(node):
    if isinstance(node, ast.Attribute):
        return node.attr
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Subscript):
        return last_name(node.value)
    if isinstance(node, ast.Call):
        return last_name(node.func)
    return ""


def settings_modules(files):
    """Paths of the settings modules Django runs with."""
    found = []
    for path in files:
        if not re.search(r"(^|/)(manage|wsgi|asgi)\.py$", path):
            continue
        src, tree = parse(path)
        if tree is None:
            continue
        root = path.rsplit("/", 1)[0] if "/" in path else ""
        for node in ast.walk(tree):
            if isinstance(node, ast.Call) and len(node.args) >= 2:
                key, value = node.args[0], node.args[1]
                if isinstance(key, ast.Constant) and isinstance(value, ast.Constant) and key.value == "DJANGO_SETTINGS_MODULE" and isinstance(value.value, str):
                    mod = value.value.replace(".", "/")
                    for base in {root, "", "src", root + "/src" if root else "src"}:
                        for cand in (f"{base}/{mod}.py" if base else f"{mod}.py", f"{base}/{mod}/__init__.py" if base else f"{mod}/__init__.py"):
                            if cand in files and cand not in found:
                                found.append(cand)
    if not found:
        found = [p for p in files if re.search(r"(^|/)settings(\.py$|/)", p) and not TESTS.search(p)]
    return found


def star_imports(path, tree, files):
    """Modules a settings module imports with *, as paths (relative or absolute)."""
    out = []
    pkg = path.rsplit("/", 1)[0] if "/" in path else ""
    for node in tree.body:
        if isinstance(node, ast.ImportFrom) and any(a.name == "*" for a in node.names):
            if node.level:
                base = pkg
                for _ in range(node.level - 1):
                    base = base.rsplit("/", 1)[0] if "/" in base else ""
                mod = ((base + "/") if base else "") + (node.module or "").replace(".", "/")
                cands = [mod + ".py", mod + "/__init__.py"]
            else:
                mod = (node.module or "").replace(".", "/")
                cands = [c for c in files if c.endswith(mod + ".py") or c.endswith(mod + "/__init__.py")]
            out += [c for c in cands if c in files]
    return out


def default_is_restricted():
    """True when the settings Django runs with set DEFAULT_PERMISSION_CLASSES to something other than AllowAny."""
    files = set(tracked_py())
    todo, seen, value = list(settings_modules(files)), set(), None
    while todo:
        path = todo.pop(0)
        if path in seen:
            continue
        seen.add(path)
        _, tree = parse(path)
        if tree is None:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Dict):
                for k, v in zip(node.keys, node.values):
                    if isinstance(k, ast.Constant) and k.value == "DEFAULT_PERMISSION_CLASSES":
                        value = v
            if isinstance(node, ast.Assign) and isinstance(node.targets[0], ast.Subscript):
                key = node.targets[0].slice
                if isinstance(key, ast.Constant) and key.value == "DEFAULT_PERMISSION_CLASSES":
                    value = node.value
        if value is not None:
            return restricted(value)
        todo += star_imports(path, tree, files)
    return False


def restricted(value):
    if isinstance(value, (ast.List, ast.Tuple)):
        names = [e.value for e in value.elts if isinstance(e, ast.Constant) and isinstance(e.value, str)]
        if len(names) != len(value.elts):
            return True  # computed entries: assume the project knows
        return bool(names) and not any(n.endswith("AllowAny") for n in names)
    return True  # computed: not ours to judge


def declares(cls):
    """cls sets a non-empty permission_classes or defines get_permissions."""
    for stmt in cls.body:
        if isinstance(stmt, (ast.Assign, ast.AnnAssign)):
            targets = stmt.targets if isinstance(stmt, ast.Assign) else [stmt.target]
            if any(isinstance(t, ast.Name) and t.id == "permission_classes" for t in targets):
                v = stmt.value
                return not (isinstance(v, (ast.List, ast.Tuple)) and not v.elts)
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name == "get_permissions":
            return True
    return None


class Classes:
    """The project's classes by name, to follow inheritance through its own bases."""

    def __init__(self, files):
        self.by_name = {}
        for path in files:
            if TESTS.search(path):
                continue
            _, tree = parse(path)
            if tree is None:
                continue
            for node in ast.walk(tree):
                if isinstance(node, ast.ClassDef):
                    self.by_name.setdefault(node.name, []).append(node)

    def resolve(self, cls, seen=None):
        """(is a DRF view, declares permissions) for cls, following project bases."""
        seen = seen or set()
        if id(cls) in seen:
            return False, False
        seen.add(id(cls))
        own = declares(cls)
        drf, decl = False, own is True
        for b in cls.bases:
            name = last_name(b)
            if DRF_BASE.match(name):
                drf = True
                continue
            for parent in self.by_name.get(name, []):
                d, p = self.resolve(parent, seen)
                drf = drf or d
                if own is None:
                    decl = decl or p
        return drf, decl


CLASSES = None


def findings_for(path):
    global CLASSES
    src, tree = parse(path)
    if tree is None:
        return []
    if CLASSES is None:
        CLASSES = Classes(tracked_py())
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef):
            drf, declared = CLASSES.resolve(node)
            if drf and not declared:
                out.append(f"{path}:{node.lineno} {node.name} gets no non-empty permission_classes, and the settings Django runs with set no DEFAULT_PERMISSION_CLASSES other than AllowAny, so DRF lets anyone call it")
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            decos = [last_name(d) for d in node.decorator_list]
            if "api_view" in decos and "permission_classes" not in decos:
                out.append(f"{path}:{node.lineno} {node.name} (@api_view) has no @permission_classes, and the settings Django runs with set no DEFAULT_PERMISSION_CLASSES other than AllowAny, so DRF lets anyone call it")
    return out


def main():
    paths = [p for p in sys.argv[2:] if p.endswith(".py")] or tracked_py()
    paths = [p for p in paths if not TESTS.search(p)]
    if not paths or default_is_restricted():
        return 0
    found = [f for p in paths for f in findings_for(p)]
    for f in found:
        print(f)
    if found:
        print("Set permission_classes on the view (IsAuthenticated, or the project's permission), or a restrictive REST_FRAMEWORK DEFAULT_PERMISSION_CLASSES in settings; a public endpoint is the user's call")
    return 1 if found else 0


if __name__ == "__main__":
    sys.exit(main())
